{"title": "老宅之谜",
  "scene": "一个小男孩打开吱呀作响的木门，进入了破旧的祠堂。祠堂内光线昏暗，地上散落着一些旧照片和奇怪的符咒。角落里有一张石桌，上面放着一本尘封的古籍。",
  "goal": "找到隐藏的宝藏线索。",
  "clue": "石桌上的古籍。",
  "choices": [
    {"id": "A", "text": "翻开石桌上的古籍", "outcome": "古籍中记载着一段模糊的藏宝图，但缺少关键信息。", "result": "partial", "next": "retry"},
    {"id": "B", "text": "检查祠堂内的旧照片", "outcome": "照片的内容看不懂，但吸引小男孩的目光，似乎有家人的笑容。", "result": "fail", "next": "retry"},
    {"id": "C", "text": "仔细观察地面的奇怪符咒", "outcome": "符咒上似乎刻有与古籍中描述的符号相符，小男孩意识到藏宝图缺失的部分可能就在这附近。", "result": "success", "next": "next_level"}
  ]}
